Translate the following MS C++ code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original MS C++ code you have to translate:
<original_code>
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    long long number;
    cin >> number;
    vector<long long> powers(19, 1);
    for (int i = 1; i <= 18; ++i) {
        powers[i] = powers[i - 1] * 10;
    }
    vector<long long> sum_powers(19, 0);
    for (int i = 1; i <= 18; ++i) {
        sum_powers[i] = sum_powers[i - 1] + powers[i];
    }
    int max_power = 1;
    while (max_power <= 18 && sum_powers[max_power] <= number) {
        ++max_power;
    }
    --max_power;

    int answer = INT_MAX;

    function<void(int, long long, int)> dfs = [&](int level, long long current_num, int cost) {
        if (current_num == 0) {
            answer = min(answer, cost);
            return;
        }
        if (level == 0) return;
        long long base = powers[level];
        int i;
        for (i = -10; i * base <= current_num; ++i);
        dfs(level - 1, current_num - (i - 1) * base, cost + abs(i - 1) * (level + 1));
        dfs(level - 1, current_num - i * base, cost + abs(i) * (level + 1));
    };

    dfs(max_power, number, 0);
    cout << answer << endl;
    return 0;
}
